    cols:[{en:'Key', bn:'কী', k:'h', r:function(r){ var n = X2_WG[r.g] || [r.g, r.g]; return '<div class="a2-cell"><b class="a2-mono a2-sm">' + esc(r.id) + '</b><span>' + Le(n[0], n[1]) + '</span></div>'; }}, {en:'English', bn:'ইংরেজি', k:'w', cls:'a2-tdm', r:function(r){ return '<span class="a2-sm">' + esc(r.en) + '</span>'; }}, {en:'Bengali', bn:'বাংলা', k:'w', cls:'a2-tdm', r:function(r){ return r.bn ? '<span class="a2-sm" lang="bn">' + esc(r.bn) + '</span>' : x2Pill('warn', Le('missing', 'নেই')); }}, {en:'Last changed', bn:'শেষ বদল', k:'x', r:function(r){ return r.at ? a2ago(r.at) + L(' ago', ' আগে') : '<span class="a2-mute">' + Le('default', 'ডিফল্ট') + '</span>'; }}],
